(function(){
  function gen(p){
    p=p||{};
    var s='root = '+(p.root?'true':'false')+'\n\n[*]\n';
    s+='indent_style = '+(p.indent_style||'space')+'\n';
    s+='indent_size = '+(p.indent_size||2)+'\n';
    s+='charset = '+(p.charset||'utf-8')+'\n';
    s+='end_of_line = '+(p.end_of_line||'lf')+'\n';
    s+='insert_final_newline = '+(p.final?'true':'false')+'\n';
    s+='trim_trailing_whitespace = '+(p.trim?'true':'false')+'\n';
    if(p.extra){ var secs=String(p.extra).split(/\r?\n/).filter(Boolean); for(var i=0;i<secs.length;i++) s+='\n'+secs[i]+'\n'; }
    return {value:s};
  }
  var API={gen:gen};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__EditorconfigForge__=API;
})();
